parameters.jsCode:
return $input.all().map(item => {
  const text = item.json.content.parts[0].text;
  const parsed = JSON.parse(text);

  return {
    json: parsed
  };
});

const items = $input.all();

const evidenceItems = $('Evidence Parser').all();
const biasItems = $('Bias Analyzer').all();

return items.map((item, index) => {

  // Evidence data
  const evidence = evidenceItems[index]?.json || {};

  // Get Bias Analyzer output directly
  let bias = biasItems[index]?.json || {};

  // If Gemini returned JSON inside content.parts[0].text, parse it
  if (bias.content?.parts?.[0]?.text) {
    try {
      bias = JSON.parse(bias.content.parts[0].text);
    } catch (error) {
      bias = {};
    }
  }

  // Normalize bias risk
  const biasRisk = String(
    bias.overall_bias_risk || "unknown"
  ).trim().toLowerCase();

  // -----------------------------
  // Evidence Support Score
  // -----------------------------

  let evidenceSupport = 0;

  if (evidence.verdict === "SUPPORTED") {
    evidenceSupport = 35;
  } else if (evidence.verdict === "PARTIALLY_SUPPORTED") {
    evidenceSupport = 18;
  } else if (evidence.verdict === "CONTRADICTED") {
    evidenceSupport = 0;
  } else {
    evidenceSupport = 10;
  }

  const confidence = Number(evidence.confidence || 0);

  evidenceSupport *= confidence;

  // -----------------------------
  // Source Quality
  // -----------------------------

  const sources = [
    ...(evidence.supporting_evidence || []),
    ...(evidence.contradicting_evidence || [])
  ];

  function getSourceQuality(url) {

    if (!url) return 0.5;

    const u = url.toLowerCase();

    if (
      u.includes(".gov") ||
      u.includes("worldbank.org") ||
      u.includes("imf.org") ||
      u.includes("federalreserve.gov")
    ) {
      return 1.0;
    }

    if (
      u.includes("nature.com") ||
      u.includes("science.org") ||
      u.includes("pubmed.ncbi.nlm.nih.gov")
    ) {
      return 1.0;
    }

    if (
      u.includes("reuters.com") ||
      u.includes("apnews.com") ||
      u.includes("bbc.com") ||
      u.includes("thehindu.com")
    ) {
      return 0.8;
    }

    if (
      u.includes("linkedin.com") ||
      u.includes("youtube.com") ||
      u.includes("facebook.com") ||
      u.includes("x.com")
    ) {
      return 0.4;
    }

    return 0.6;
  }

  let sourceQuality = 0;

  if (sources.length > 0) {

    const qualities = sources.map(source =>
      getSourceQuality(source.source_url)
    );

    sourceQuality =
      (
        qualities.reduce((sum, value) => sum + value, 0) /
        qualities.length
      ) * 25;
  }

  // -----------------------------
  // Source Agreement
  // -----------------------------

  const supportingCount =
    (evidence.supporting_evidence || []).length;

  const sourceAgreement =
    Math.min(supportingCount / 3, 1) * 20;

  // -----------------------------
  // Evidence Coverage
  // -----------------------------

  const evidenceCoverage =
    supportingCount > 0 ||
    (evidence.contradicting_evidence || []).length > 0
      ? 10
      : 0;

  // -----------------------------
  // Bias Penalty
  // -----------------------------

  let biasPenalty = 0;

  if (biasRisk === "medium") {
    biasPenalty = 5;
  } else if (biasRisk === "high") {
    biasPenalty = 10;
  }

  // -----------------------------
  // Final Score
  // -----------------------------

  let finalScore =
    evidenceSupport +
    sourceQuality +
    sourceAgreement +
    evidenceCoverage -
    biasPenalty;

  finalScore = Math.max(0, Math.min(100, finalScore));

  // -----------------------------
  // Final Verdict
  // -----------------------------

  let finalVerdict;

  if (finalScore >= 75) {
    finalVerdict = "HIGH_CREDIBILITY";
  } else if (finalScore >= 50) {
    finalVerdict = "MODERATE_CREDIBILITY";
  } else if (finalScore >= 25) {
    finalVerdict = "LOW_CREDIBILITY";
  } else {
    finalVerdict = "VERY_LOW_CREDIBILITY";
  }

  // -----------------------------
  // Output
  // -----------------------------

  return {
    json: {

      claim_id:
        evidence.claim_id ||
        bias.claim_id ||
        `C00${index + 1}`,

      claim:
        evidence.claim || "",

      evidence_verdict:
        evidence.verdict || "UNVERIFIED",

      confidence,

      evidence_support_score:
        Number(evidenceSupport.toFixed(2)),

      source_quality_score:
        Number(sourceQuality.toFixed(2)),

      source_agreement_score:
        Number(sourceAgreement.toFixed(2)),

      evidence_coverage_score:
        evidenceCoverage,

      bias_penalty:
        biasPenalty,

      final_score:
        Number(finalScore.toFixed(2)),

      final_verdict:
        finalVerdict,

      // IMPORTANT
      bias_risk:
        biasRisk,

      bias_indicators:
        bias.bias_indicators || [],

      score_breakdown: {
        evidence_support: "35 points maximum",
        source_quality: "25 points maximum",
        source_agreement: "20 points maximum",
        evidence_coverage: "10 points maximum",
        bias_penalty: "0 to -10 points"
      }
    }
  };
});

const items = $input.all();

const totalClaims = items.length;

// Calculate overall score from all claim final scores
const scores = items
  .map(item => Number(item.json.final_score))
  .filter(score => !isNaN(score));

const overallScore = scores.length
  ? Number((scores.reduce((a, b) => a + b, 0) / scores.length).toFixed(2))
  : 0;

// Decide overall verdict
let overallVerdict;

if (overallScore >= 80) {
  overallVerdict = "HIGH_CREDIBILITY";
} else if (overallScore >= 60) {
  overallVerdict = "MODERATE_CREDIBILITY";
} else if (overallScore >= 40) {
  overallVerdict = "LOW_CREDIBILITY";
} else {
  overallVerdict = "VERY_LOW_CREDIBILITY";
}

// Add the overall values to EVERY claim item
return items.map(item => ({
  json: {
    overall_score: overallScore,
    overall_verdict: overallVerdict,
    total_claims: totalClaims,

    claim_id: item.json.claim_id,
    claim: item.json.claim,
    evidence_verdict: item.json.evidence_verdict,
    confidence: item.json.confidence,
    final_score: item.json.final_score,
    final_verdict: item.json.final_verdict,
    bias_risk: item.json.bias_risk
  }
}));
